  let sending = false;
  let queuedPick;
  const queuedPrizes = [];
  let refreshPending = false;
  let streaming = false;
  let failures = 0;
  let unavailable = false;

  function schedule() {
    clearTimeout(timer);
    if (unavailable || sending) return;
    const hasCounter = root.dataset.liveGame === "stage" && ["lobby", "open"].includes(phase());
    // With push connected, phones only need a periodic heartbeat and the
    // stage polls for counters (which aren't part of the moderator's stream).
    const steady = streaming && !hasCounter ? 10000 : interval;
    const pace = document.hidden ? Math.max(steady, 3500) : steady;
    const backoff = Math.min(pace * 2 ** failures, 10000);
    timer = setTimeout(poll, backoff * (0.85 + Math.random() * 0.3));
  }

  function sync() {
    clearTimeout(timer);
    refreshPending = true;
    if (!currentPoll && !sending && !unavailable) poll();
  }

  function afterRequest() {
    if (refreshPending && !unavailable) poll();
    else schedule();
  }

